IspfTableHost TRAIT (crates/ff-desktop/src/shell/ispf_table_editor/state.rs) -- FINAL method set + signatures:
  trait IspfTableHost {
    type Row;
    fn columns(&self) -> &[ColumnSpec];
    fn line_command_set(&self) -> LineCommandSet;
